function showEvidence(){const record=s.evidence.at(-1),c=$('evidenceCanvas'),ct=c.getContext('2d');ct.clearRect(0,0,c.width,c.height);$('traceCanvas').hidden=true;$('traceLabel').textContent='';if(!record){$('evidenceStatus').textContent='No evidence loaded. State exports preserve loaded observation records and provenance.';$('evidenceDetails').textContent='';return;}const plot=evidencePlot(record),k=Math.min((c.width-40)/plot.width,(c.height-40)/plot.height),p=xy=>[20+xy[0]*k,20+xy[1]*k];ct.strokeStyle='#526b59';ct.strokeRect(20,20,plot.width*k,plot.height*k);for(const a of plot.points){const q=p(a.xy);ct.fillStyle=a.group==='top_edge'?'#efd093':a.group==='bottom_edge'?'#9fcfd0':'#cbabdf';ct.beginPath();ct.arc(...q,3,0,Math.PI*2);ct.fill();}for(const a of plot.contours??[]){if(a.source_id!==record.alignment_sample?.source_id)continue;ct.strokeStyle='#cbabdf';ct.beginPath();a.xy.forEach((xy,i)=>{const q=p(xy);i?ct.lineTo(...q):ct.moveTo(...q)});ct.stroke();}for(const a of plot.segments){const q=p(a.xy[0]),r=p(a.xy[1]);ct.strokeStyle='#efd093';ct.beginPath();ct.moveTo(...q);ct.lineTo(...r);ct.stroke();ct.fillStyle='#efd093';ct.fillText(a.id,...q);}const trace=record.traces?.[0];if(trace){const tc=$('traceCanvas'),cx=tc.getContext('2d'),src=record.sources.find(a=>a.id===trace.source_id),k=Math.min((tc.width-40)/src.width_px,(tc.height-40)/src.height_px);tc.hidden=false;cx.clearRect(0,0,tc.width,tc.height);cx.strokeStyle='#cbabdf';cx.beginPath();trace.contour_px.forEach(([x,y],i)=>{i?cx.lineTo(20+x*k,20+y*k):cx.moveTo(20+x*k,20+y*k)});cx.stroke();$('traceLabel').textContent=`Separate source frame: ${trace.source_id} · ${trace.contour_px.length} exact vertices · ${trace.coverage} · no physical scale or occurrence registration.`;}$('evidenceStatus').textContent=`${s.evidence.length} evidence record(s) saved · ${record.status}. No world registration or physical scale applied.`;$('evidenceDetails').textContent=JSON.stringify({source:record.source??record.sources,ingestion:record.ingestion??'intact source evidence; partial coverage remains uncalibrated',limitations:record.limitations??record.alignment_sample.limits,calibration:record.calibration??'none; curve observations are not established physical correspondences'},null,2);}
function acceptEvidence(raw){const record=validateEvidence(JSON.parse(raw));if(s.evidence.length>=10)throw Error('Maximum10 evidence records; reset before loading more');s.evidence=[...s.evidence,record];showEvidence();notice('Evidence saved. Geometry unchanged; no calibration claimed.');}
for(const[id,file]of[['loadBoundary','boundary-observations.json'],['loadRubbing','rubbing-glyph-sample.json']])$(id).onclick=async()=>{const operation=userOperation();try{const response=await fetch('./evidence/'+file);if(!response.ok)throw Error('Evidence fetch failed');const raw=await response.text();if(operation!==operationGeneration)return;acceptEvidence(raw);}catch(e){if(operation===operationGeneration)notice('Evidence rejected: '+e.message);}};
$('importEvidence').onclick=()=>{userOperation();$('evidenceFile').click();};$('evidenceFile').onchange=async()=>{const operation=userOperation();try{const raw=await $('evidenceFile').files[0].text();if(operation!==operationGeneration)return;acceptEvidence(raw);}catch(e){if(operation===operationGeneration)notice('Evidence rejected: '+e.message);}};

